1	use std::collections::{BTreeMap, BTreeSet};
2	use std::path::PathBuf;
3	
4	use callisto_model::{
5	    BumpReason, ConfigKey, Coverage, DepEdge, DepKind, DepLocator, DepSpec, Diagnostic, DiagnosticCode,
6	    DiagnosticSeverity, Ecosystem, GrammarMismatch, PackageId, Severity, Version,
7	};
8	
9	use crate::config::GroupTable;
10	use crate::config::{CascadeConfig, CascadeMode};
11	use crate::error::GraphError;
12	use crate::identity::IdentityIndex;
13	use crate::resolver::DependencyResolver;
14	use crate::tags::TagIndex;
15	
16	#[derive(Clone, Debug, PartialEq, Eq)]
17	pub struct CascadeDecision {
18	    pub severity: Severity,
19	    pub rewrite: bool,
20	    pub governed_by: Option<ConfigKey>,
21	    pub escalated: bool,
22	    pub unknown_coverage: bool,
23	}
24	
25	pub fn cascade_action(kind: DepKind, coverage: Coverage, source: Severity, cfg: &CascadeConfig) -> CascadeDecision {
26	    use Coverage::*;
27	    use DepKind::*;
28	
29	    let effective = match (cfg.mode, coverage) {
30	        (CascadeMode::Always, _) => DoesNotCover,
31	        (CascadeMode::OutOfRange, Covers) => Covers,
32	        (CascadeMode::OutOfRange, DoesNotCover) => DoesNotCover,
33	        (CascadeMode::OutOfRange, Unknown) => Covers,
34	    };
35	
36	    let rewrite = matches!(coverage, DoesNotCover);
37	
38	    let (severity, governed_by, escalated) = match (kind, effective) {
39	        (Runtime | Optional | Build, Covers) => (Severity::None, None, false),
40	        (Runtime | Optional | Build, DoesNotCover) => (
41	            cfg.bump_severity.as_severity(),
42	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
43	            false,
44	        ),
45	        (Peer, Covers) => (Severity::None, None, false),
46	        (Peer, DoesNotCover)
47	            if cfg.peer_escalation
48	                && matches!(coverage, DoesNotCover)
49	                && matches!(source, Severity::Minor | Severity::Major) =>
50	        {
51	            (Severity::Major, Some(ConfigKey::CASCADE_PEER_ESCALATION), true)
52	        }
53	        (Peer, DoesNotCover) => (
54	            cfg.bump_severity.as_severity(),
55	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
56	            false,
57	        ),
58	        _ => (Severity::None, None, false),
59	    };
60	
61	    let governed_by = match (cfg.mode, coverage, severity) {
62	        (CascadeMode::Always, Covers | Unknown, s) if s != Severity::None => Some(ConfigKey::CASCADE_MODE),
63	        _ => governed_by,
64	    };
65	
66	    CascadeDecision {
67	        severity,
68	        rewrite,
69	        governed_by,
70	        escalated,
71	        unknown_coverage: matches!(coverage, Unknown),
72	    }
73	}
