165	pub(crate) fn dependency_rewrite_key(edge: &DepEdge) -> RewriteKey {
166	    RewriteKey {
167	        target: if edge.inherited {
168	            DepWriteTarget::CargoWorkspaceDependency {
169	                root_manifest: edge.from_manifest.clone(),
170	            }
171	        } else {
172	            DepWriteTarget::Manifest(edge.from_manifest.clone())
173	        },
174	        name: edge.name.clone(),
175	        kind: if edge.inherited { None } else { Some(edge.kind) },
176	        // An inherited declaration is rewritten once, in the workspace root, whichever member table names it.
177	        locator: if edge.inherited {
178	            DepLocator::default()
179	        } else {
180	            edge.locator.clone()
181	        },
182	    }
183	}
