513	fn bump_target<D: DependencyResolver>(
514	    id: &PackageId,
515	    sev: Severity,
516	    input: &CascadeInput<'_, D>,
517	) -> Result<Version, GraphError> {
518	    // A fixed-group member's own bump is never visible: its target is always the group's aligned version.
519	    if let Some(group) = input.groups.fixed_group_of(id) {
520	        let live: Vec<PackageId> = group
521	            .package_members()
522	            .filter(|member| input.base.contains_key(*member))
523	            .cloned()
524	            .collect();
525	        if !live.is_empty() {
526	            return crate::groups::fixed_group_target(&group.name, &live, input.base, sev, input.tags, input.pre);
527	        }
528	    }
529	
530	    let base = input.base.get(id).cloned().ok_or_else(|| {
531	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
532	            path: PathBuf::from(id.name()),
533	            field: "version",
534	        })
535	    })?;
536	
537	    // PreMode::Exit falls through to a plain `versioning.bump`, which strips a matching pre-release tag directly.
538	    crate::groups::versioned_bump(id, &base, sev, input.pre)
539	}
