541	#[allow(clippy::too_many_arguments)]
542	fn raise<D: DependencyResolver>(
543	    pkg: &PackageId,
544	    sev: Severity,
545	    decision: &CascadeDecision,
546	    via: &PackageId,
547	    edge: &DepEdge,
548	    dependency_to: &Version,
549	    out: &mut CascadeOutcome,
550	    groups: &GroupTable,
551	    worklist: &mut BTreeSet<PackageId>,
552	    input: &CascadeInput<'_, D>,
553	) -> Result<bool, GraphError> {
554	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
555	    if sev <= cur_sev {
556	        return Ok(false);
557	    }
558	
559	    out.severities.insert(pkg.clone(), sev);
560	
561	    let new_reason = if decision.escalated {
562	        BumpReason::PeerEscalation {
563	            via: via.clone(),
564	            spec: edge.spec.render(),
565	        }
566	    } else {
567	        BumpReason::Cascade {
568	            via: via.clone(),
569	            dep_kind: edge.kind,
570	            spec: edge.spec.render(),
571	            dependency_to: dependency_to.clone(),
572	        }
573	    };
574	    out.reasons.insert(pkg.clone(), new_reason);
575	
576	    if let Some(ref gov) = decision.governed_by {
577	        out.governed_by.insert(pkg.clone(), gov.clone());
578	    }
579	
580	    let new_t = bump_target(pkg, sev, input)?;
581	    out.targets.insert(pkg.clone(), new_t);
582	    worklist.insert(pkg.clone());
583	
584	    for sib in groups.fixed_siblings(pkg) {
585	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
586	        if sev > sib_sev {
587	            out.severities.insert(sib.clone(), sev);
588	            out.reasons.insert(
589	                sib.clone(),
590	                BumpReason::FixedGroupUnion {
591	                    group: groups
592	                        .fixed_group_of(pkg)
593	                        .expect("a fixed-group sibling implies the package has a fixed group")
594	                        .name
595	                        .clone(),
596	                },
597	            );
598	            let sib_t = bump_target(sib, sev, input)?;
599	            out.targets.insert(sib.clone(), sib_t);
600	            worklist.insert(sib.clone());
601	        }
602	    }
603	
604	    Ok(true)
605	}
