use std::collections::BTreeMap;
use std::ops::{Deref, Index};

use callisto_model::{PackageId, Version};

/// Each releasing package's target once the solver has stopped moving it.
///
/// Range rewrites and the unrewritable-range check take only a [`ConvergedTarget`] read from here, so a target that
/// group alignment may still move can never reach a dependent's manifest.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ConvergedTargets(BTreeMap<PackageId, Version>);

impl ConvergedTargets {
    /// Consumes the working map, so nothing can move a target once it is settled.
    pub(super) fn settle(targets: BTreeMap<PackageId, Version>) -> Self {
        Self(targets)
    }

    pub fn get(&self, id: &PackageId) -> Option<ConvergedTarget<'_>> {
        self.0.get(id).map(ConvergedTarget)
    }

    pub fn contains_key(&self, id: &PackageId) -> bool {
        self.0.contains_key(id)
    }

    pub fn keys(&self) -> impl Iterator<Item = &PackageId> {
        self.0.keys()
    }

    pub fn iter(&self) -> impl Iterator<Item = (&PackageId, ConvergedTarget<'_>)> {
        self.0.iter().map(|(id, version)| (id, ConvergedTarget(version)))
    }

    pub fn len(&self) -> usize {
        self.0.len()
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }
}

impl Index<&PackageId> for ConvergedTargets {
    type Output = Version;

    fn index(&self, id: &PackageId) -> &Version {
        &self.0[id]
    }
}

impl<'a> IntoIterator for &'a ConvergedTargets {
    type Item = (&'a PackageId, ConvergedTarget<'a>);
    type IntoIter = Box<dyn Iterator<Item = Self::Item> + 'a>;

    fn into_iter(self) -> Self::IntoIter {
        Box::new(self.iter())
    }
}

/// One package's settled target, borrowed from [`ConvergedTargets`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ConvergedTarget<'a>(&'a Version);

impl<'a> ConvergedTarget<'a> {
    pub fn version(self) -> &'a Version {
        self.0
    }
}

impl Deref for ConvergedTarget<'_> {
    type Target = Version;

    fn deref(&self) -> &Version {
        self.0
    }
}

